let basket={};try{const saved=JSON.parse(localStorage.getItem('salsal-basket')||'{}');for(const p of products)if(Number.isInteger(saved[p.id])&&saved[p.id]>0&&saved[p.id]<=99)basket[p.id]=saved[p.id];}catch{}
let category='הכול',promos=false;const $=id=>document.getElementById(id);const money=n=>new Intl.NumberFormat('he-IL',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n);const min=p=>Math.min(...p.prices);const gap=p=>Math.max(...p.prices)-min(p);
function render(){const query=$('search').value.trim().toLowerCase();let list=products.filter(p=>(category==='הכול'||p.category===category)&&(!promos||p.promo)&&(!query||[p.name,p.brand,p.barcode].join(' ').toLowerCase().includes(query)));if($('sort').value==='saving')list.sort((a,b)=>gap(b)-gap(a));if($('sort').value==='price')list.sort((a,b)=>min(a)-min(b));$('resultCount').textContent=`${list.length} מוצרים${promos?' במבצע מאומת':''}`;$('products').innerHTML=list.length?list.map(p=>`<article class="product"><div class="product-top">${p.image?`<img class="product-image" src="${p.image}" alt="${p.name} ${p.brand}" loading="lazy" onerror="this.style.display='none'">`:''}<div><h3>${p.name}</h3><div class="meta">${p.brand} · ${p.size}</div></div></div><div class="price-row"><div><div class="meta">מחיר מאומת עדיין לא זמין</div></div></div><div class="card-actions"><button class="compare" data-compare="${p.id}">מצב נתונים ↗</button><button class="add" data-add="${p.id}" aria-label="הוספת ${p.name} לסל">＋ לסל</button></div></article>`).join(''):'<div class="no-results">לא מצאנו מוצר מתאים.<br>כדאי לנסות שם אחר או לבחור ״הכול״.</div>';$('categories').innerHTML=['הכול','מוצרי חלב','מזווה','חטיפים ומתוקים','משקאות'].map(c=>`<button data-category="${c}" class="${c===category?'active':''}" aria-pressed="${c===category}">${c}</button>`).join('');$('allNav').classList.toggle('nav-active',!promos);$('promoNav').classList.toggle('nav-active',promos);}
function renderBasket(){const entries=products.filter(p=>basket[p.id]);$('basketCount').textContent=Object.values(basket).reduce((a,b)=>a+b,0);$('basketItems').innerHTML=entries.length?entries.map(p=>`<div class="basket-item"><strong>${p.name}</strong><div class="meta">${p.brand} · ${p.size}</div><div class="quantity"><button data-change="${p.id}" data-delta="-1" aria-label="הפחתת ${p.name}">−</button><span>${basket[p.id]}</span><button data-change="${p.id}" data-delta="1" aria-label="הוספת ${p.name}">+</button></div></div>`).join(''):'<div class="empty"><div class="empty-icon" aria-hidden="true">＋</div><strong>מה קונים היום?</strong>אפשר לשמור מוצרים ברשימה.<br>השוואת העלות ממתינה למחירים מאומתים.</div>';$('basketTotals').innerHTML=entries.length?'<p class="basket-note">לא ניתן לחשב את מחיר הסל: עדיין אין מחירים מאומתים למוצרים.</p>':'';try{localStorage.setItem('salsal-basket',JSON.stringify(basket));}catch{}}
function change(id,delta){basket[id]=Math.min(99,(basket[id]||0)+delta);if(basket[id]<=0)delete basket[id];renderBasket();}let toastTimer;function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),1800);}
function detail(id){const p=products.find(p=>p.id===id);$('detailContent').innerHTML=`<h2>${p.name}</h2><p>${p.brand} · ${p.size}</p><p>אין כרגע מחיר מאומת למוצר זה באף רשת. המחירים שהוצגו קודם היו מומצאים לצורך הדגמה והוסרו.</p><p>מחיר יוצג רק לאחר חיבור למקור נתונים, עם זיהוי סניף וזמן עדכון.</p>`;$('detail').showModal();}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){change(+add.dataset.add,1);toast('המוצר נוסף לסל');}const c=e.target.closest('[data-category]');if(c){category=c.dataset.category;render();}const d=e.target.closest('[data-compare]');if(d)detail(+d.dataset.compare);const q=e.target.closest('[data-change]');if(q)change(+q.dataset.change,+q.dataset.delta);});$('search').addEventListener('input',render);$('sort').addEventListener('change',render);$('allNav').onclick=()=>{promos=false;render();};$('promoNav').onclick=()=>{promos=true;render();};$('clear').onclick=()=>{basket={};renderBasket();};document.querySelector('.close').onclick=()=>$('detail').close();$('detail').addEventListener('click',e=>{if(e.target===$('detail')){const r=$('detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('detail').close();}});$('sourcesBtn').onclick=()=>{$('detailContent').innerHTML='<h2>מאיפה מגיעים המחירים?</h2><p>המחירים המומצאים שהוצגו בגרסה הראשונה הוסרו. כרגע אין באתר מחירים, מבצעים או השוואת עלות סל מאומתים.</p><p>החיבור המתוכנן הוא לקובצי שקיפות המחירים והמבצעים שמפרסמות הרשתות. כל מחיר ישויך לרשת, לסניף ולזמן העדכון שלו. תנאי מועדון, כמות מינימלית ותוקף מבצע יוצגו לצד ההצעה.</p><p>בדיקת קבצים חדשים מתוכננת בכל 15 דקות. מידע חדש יוכל להופיע רק לאחר שהרשת תפרסם אותו; המערכת אינה מחוברת כרגע לעדכונים אוטומטיים.</p><p><a href="https://prices.shufersal.co.il/" target="_blank" rel="noopener noreferrer">אתר שקיפות המחירים הרשמי של שופרסל ↗</a></p>';$('detail').showModal();};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('detail').open){e.preventDefault();$('search').focus();}});render();renderBasket();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'add_products_to_basket',description:'Add quantities of demo products to the visible local comparison basket. Does not purchase anything.',inputSchema:{type:'object',properties:{items:{type:'array',items:{type:'object',properties:{id:{type:'integer'},quantity:{type:'integer',minimum:1,maximum:99}},required:['id','quantity'],additionalProperties:false}}},required:['items'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Array.isArray(input.items)||input.items.length>100||!input.items.every(i=>products.some(p=>p.id===i.id)&&Number.isInteger(i.quantity)&&i.quantity>0&&i.quantity<=99))throw new Error('Invalid product IDs or quantities');for(const i of input.items)change(i.id,i.quantity);return {mode:'demo',basket:{...basket}};}})).catch(()=>{});}catch{}}
